    "title": "Syntax highlighting demo",
    "subtitle": "Highlighters shipped with this theme.",
    "excerpt": "This page is a demo of the different styles ofsyntax highlighting shipped by default with thistheme. Just make your selection below.",
    "content": "Select a highlighting style to preview it, then copy the displayed setting into chulapa-skin.highlight in _config.yml. Restart Jekyll to apply it. Changing this preview does not save the style on your own website. Select style None chulapa-skin: highlight: Demo of the different pieces of code for testing syntax highlighting. JavaScript // Cross-browser xml parsing var parseXML = function( data ) { var xml, tmp; if ( !data || typeof data !== \"string\" ) { return null; } try { if ( window.DOMParser ) { // Standard tmp = new DOMParser(); xml = tmp.parseFromString( data , \"text/xml\" ); } else { // IE xml = new ActiveXObject( \"Microsoft.XMLDOM\" ); xml.async = false; xml.loadXML( data ); } } catch( e ) { xml = undefined; } if ( !xml || !xml.documentElement || xml.getElementsByTagName( \"parsererror\" ).length ) { jQuery.error( \"Invalid XML: \" + data ); } return xml; }; // Bind a function to a context, optionally partially applying any arguments. var proxy = function( fn, context ) { var tmp, args, proxy; if ( typeof context === \"string\" ) { tmp = fn[ context ]; context = fn; fn = tmp; } // Quick check to determine if target is callable, in the spec // this throws a TypeError, but we will just return undefined. if ( !jQuery.isFunction( fn ) ) { return undefined; } // Simulated bind args = core_slice.call( arguments, 2 ); proxy = function() { return fn.apply( context || this, args.concat( core_slice.call( arguments ) ) ); }; // Set the guid of unique handler to the same of original handler, so it can be removed proxy.guid = fn.guid = fn.guid || jQuery.guid++; return proxy; }; Sound.play = function() {} Sound.prototype = { something; } Sound.prototype.play = function() {} Sound.prototype.play = myfunc var parser = document.createElement('a'); parser.href = \"http://example.com:3000/pathname/?search=test#hash\"; parser.hostname; // =&gt; \"example.com\" Python #!/usr/bin/python # -*- coding: utf-8 -*- import re import sublime import sublime_plugin from datetime import datetime class SublimeTasksBase(sublime_plugin.TextCommand): def run(self, edit): self.open_tasks_bullet = self.view.settings().get('open_tasks_bullet') self.done_tasks_bullet = self.view.settings().get('done_tasks_bullet') self.date_format = self.view.settings().get('date_format') if self.view.settings().get('done_tag'): self.done_tag = \"@done\" else: self.done_tag = \"\" self.runCommand(edit) class NewCommand(SublimeTasksBase): def runCommand(self, edit): for region in self.view.sel(): line = self.view.line(region) line_contents = self.view.substr(line).rstrip() has_bullet = re.match('^(\\s*)[' + re.escape(self.open_tasks_bullet) + re.escape(self.done_tasks_bullet) + ']', self.view.substr(line)) current_scope = self.view.scope_name(self.view.sel()[0].b) if has_bullet: grps = has_bullet.groups() line_contents = self.view.substr(line) + '\\n' + grps[0] + self.open_tasks_bullet + ' ' self.view.replace(edit, line, line_contents) elif 'header' in current_scope: header = re.match('^(\\s*)\\S+', self.view.substr(line)) if header: grps = header.groups() line_contents = self.view.substr(line) + '\\n' + grps[0] + ' ' + self.open_tasks_bullet + ' ' else: line_contents = + self.open_tasks_bullet + ' ' self.view.replace(edit, line, line_contents) end = self.view.sel()[0].b pt = sublime.Region(end, end) self.view.sel().clear() self.view.sel().add(pt) else: has_space = re.match('^(\\s+)(.*)', self.view.substr(line)) if has_space: grps = has_space.groups() spaces = grps[0] line_contents = spaces + self.open_tasks_bullet + ' ' + grps[1] self.view.replace(edit, line, line_contents) else: line_contents = ' ' + self.open_tasks_bullet + ' ' + self.view.substr(line) self.view.replace(edit, line, line_contents) end = self.view.sel()[0].b pt = sublime.Region(end, end) self.view.sel().clear() self.view.sel().add(pt) CSS body { font-family: arial; } h1, p, table {...",
